 const[tab,setTab]=useState("overview"),[tasks,setTasks]=useState<Task[]>(initialTasks),[sources,setSources]=useState<Source[]>(initialSources),[selected,setSelected]=useState<Source|undefined>(initialSources[0]),[rules,setRules]=useState<Rule[]>(initialRules);
