 async function importDoc(file?:File){if(!file)return;if(!/\.(docx|pdf|xlsx|xls)$/i.test(file.name))return toast.error("Hỗ trợ Word (.docx), PDF, Excel (.xlsx, .xls)");if(file.size>10*1024*1024)return toast.error("File vượt quá 10 MB");const kind=importKindRef.current;setImporting(true);try{const f=new FormData();f.append("file",file);const r=await fetch("/api/import-source",{method:"POST",body:f});if(r.status===413)throw new Error("File quá lớn. Hãy chọn file nhỏ hơn 10 MB.");const d=await r.json() as {error?:string;title?:string;text:string;warnings?:string[]};if(!r.ok)throw new Error(d.error||"Không thể đọc file");const name=d.title||file.name.replace(/\.(docx|pdf|xlsx|xls)$/i,"");const s:Source={id:Date.now(),kind,name,role:kind==="event"?"Sự kiện":"Chưa xác định",company:"Chưa xác định",event:kind==="event"?name:"Chưa xác định",file:file.name,excerpt:d.text,imported:"Vừa xong"};setSourceCategory(kind);setSources(v=>[s,...v]);setSelected(s);setTab("sources");toast.success("Đã đọc và thêm hồ sơ vào kho dữ liệu");if(d.warnings?.length)toast.warning(d.warnings.join("\n"),{duration:10000})}catch(e){toast.error(e instanceof Error?e.message:"Import thất bại")}finally{setImporting(false);if(fileRef.current)fileRef.current.value=""}}
