 async function vertex(prompt:string,options?:{jsonMode?:boolean}){if(!serviceAccountJson)throw new Error("Chọn file service account JSON trong tab Kết nối AI trước");const model=models.find(item=>item.output==="Text")?.id||"gemini-2.5-flash-lite";for(let attempt=0;attempt<4;attempt++){const r=await fetch("/api/vertex",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({credentials:serviceAccountJson,model,prompt,jsonMode:options?.jsonMode===true})});const d=await r.json() as {text?:string;error?:string};if(r.ok)return String(d.text||"");if(r.status!==429||attempt===3)throw new Error(d.error);await new Promise(resolve=>window.setTimeout(resolve,1000*2**attempt))}throw new Error("Không thể kết nối Vertex AI")}
